#!/usr/bin/env python3
"""
MT19937 predictor for Mersenne Twister randomness recovery
Implementation inspired by:
- https://github.com/kmyk/mersenne-twister-predictor
- https://github.com/tna0y/Python-random-module-cracker

This class allows you to:
1. Feed it outputs from a MT19937 RNG
2. Then predict future outputs
"""

class MT19937Predictor:
    """Predict outputs from MT19937 PRNG after observing enough outputs."""
    def __init__(self):
        self.index = 624
        self.mt = [0] * 624
        self.initialized = False

    def setrand_int32(self, y):
        """Set a random number generated from the RNG."""
        # If we have enough samples, the state is fully populated
        if self.index >= 624:
            self._twist()

        # Reverse temper the output and use it as state
        self.mt[self.index] = self._untemper(y)
        self.index += 1
        self.initialized = self.index >= 624

    def _untemper(self, y):
        """Reverse the tempering transformation."""
        # Reverse step: y = y ^ ((y >> 18))
        y = self._reverse_right_shift_xor(y, 18)

        # Reverse step: y = y ^ ((y << 15) & 0xefc60000)
        y = self._reverse_left_shift_xor_and(y, 15, 0xefc60000)

        # Reverse step: y = y ^ ((y << 7) & 0x9d2c5680)
        y = self._reverse_left_shift_xor_and(y, 7, 0x9d2c5680)

        # Reverse step: y = y ^ ((y >> 11))
        y = self._reverse_right_shift_xor(y, 11)

        return y

    def _reverse_right_shift_xor(self, y, shift):
        """Reverse operation: y = y ^ (y >> shift)"""
        mask = ((1 << 32) - 1)

        x = y
        for i in range(32 // shift + 1):
            x = y ^ ((x >> shift) & mask)

        return x

    def _reverse_left_shift_xor_and(self, y, shift, mask):
        """Reverse operation: y = y ^ ((y << shift) & mask)"""
        x = y
        for i in range(32 // shift + 1):
            x = y ^ ((x << shift) & mask)

        return x

    def _twist(self):
        """Perform the MT19937 twist operation."""
        for i in range(624):
            y = ((self.mt[i] & 0x80000000) + (self.mt[(i + 1) % 624] & 0x7fffffff)) & 0xffffffff
            self.mt[i] = (self.mt[(i + 397) % 624] ^ (y >> 1)) & 0xffffffff

            if y % 2 != 0:  # y is odd
                self.mt[i] = (self.mt[i] ^ 0x9908b0df) & 0xffffffff

        self.index = 0

    def _temper(self, y):
        """Apply the tempering transformation."""
        y = y ^ ((y >> 11) & 0xffffffff)
        y = y ^ ((y << 7) & 0x9d2c5680)
        y = y ^ ((y << 15) & 0xefc60000)
        y = y ^ (y >> 18)
        return y & 0xffffffff

    def _extract_number(self):
        """Extract a random number using the same algorithm as MT19937."""
        if not self.initialized:
            raise ValueError("Generator not initialized with enough values.")

        if self.index >= 624:
            self._twist()

        y = self.mt[self.index]
        self.index += 1

        return self._temper(y)

    def predict_getrandbits(self, bits):
        """Predict the next output from getrandbits()."""
        if bits <= 0:
            raise ValueError("bits must be greater than 0")

        if bits <= 32:
            return self._extract_number() >> (32 - bits)

        # For more than 32 bits, we need multiple extractions
        result = 0
        n = (bits - 1) // 32 + 1  # Number of 32-bit chunks needed

        for _ in range(n):
            result = (result << 32) | self._extract_number()

        # Mask out extra bits
        return result >> (32 * n - bits)

    def predict_randrange(self, start, stop=None, step=1):
        """Predict the next output from randrange()."""
        if stop is None:
            stop = start
            start = 0

        width = stop - start
        if width <= 0:
            raise ValueError("Range width must be positive")

        if width >= 2**32:
            # For large ranges, Python uses multiple random values
            # This is a simplified implementation
            bits = width.bit_length()
            return start + (self.predict_getrandbits(bits) % width)
        else:
            # Standard implementation for smaller ranges
            return start + (self._extract_number() % width)

    def predict_randint(self, a, b):
        """Predict the next output from randint()."""
        return self.predict_randrange(a, b + 1)

    def predict_random(self):
        """Predict the next output from random()."""
